// Obtener el input
const input = $input.first().json;

// FILTRAR: Solo procesar si es un mensaje entrante (no notificaciones de estado)
if (!input.messages || input.messages.length === 0) {
  console.log('⏭️ [Extraer Datos] Ignorando notificación de estado:', input.statuses?.[0]?.status);
  return [];
}

// Extraer datos del mensaje
const phoneNumber = input.messages[0].from;
const messageText = input.messages[0].text.body;
const userName = input.contacts[0].profile.name;
const messageId = input.messages[0].id;
const timestamp = input.messages[0].timestamp;

console.log('📱 [Extraer Datos] Mensaje recibido de:', phoneNumber);
console.log('💬 [Extraer Datos] Contenido:', messageText);

// Retornar datos limpios
return [{
  json: {
    phone_number: phoneNumber,
    message: messageText,
    user_name: userName,
    message_id: messageId,
    timestamp: timestamp,
    raw_data: input
  }
}];

const session = $input.first().json;
const userMessage = $('Extraer Datos WhatsApp').first().json.message;

const preferencesData = session.preferences_captured || {};
const collectedData = preferencesData.collected_data || {};

const context = {
  session_id: session.session_id,
  phone_number: session.channel_id,
  message: userMessage,
  session_context: `
CONTEXTO DE LA SESIÓN ANTERIOR:
- Estado del onboarding: ${preferencesData.onboarding_status || 'iniciado'}
- Datos ya recopilados:
  * Nombre del restaurante: ${collectedData.restaurant_name || 'pendiente'}
  * Nombre del contacto: ${collectedData.contact_name || 'pendiente'}
  * Ciudad: ${collectedData.city || 'pendiente'}
  * Tipo de negocio: ${collectedData.business_type || 'pendiente'}

El usuario está continuando su registro. Continúa desde donde quedaste pidiendo los datos que faltan.
  `.trim(),
  collected_data: collectedData
};

return [{ json: context }];

const agentOutput = $input.first().json.output;
const phoneNumber = $('Extraer Datos WhatsApp').first().json.phone_number;

const isComplete = agentOutput.includes('CADASTRO_COMPLETO');

function mapBusinessType(tipo) {
  const mapping = {
    'restaurante': 'restaurant',
    'padaria': 'cafe',
    'cafeteria': 'cafe',
    'lanchonete': 'cafe',
    'bistro': 'bistro',
    'brasserie': 'brasserie',
    'hotel': 'hotel',
    'catering': 'catering',
    'buffet': 'catering'
  };

  return mapping[tipo.toLowerCase()] || 'restaurant';
}

let parsedData = {
  restaurant_name: null,
  contact_name: null,
  city: null,
  business_type: null
};

if (isComplete) {
  const lines = agentOutput.split('\n');

  for (const line of lines) {
    if (line.includes('Nome Restaurante:')) {
      parsedData.restaurant_name = line.split(':')[1].trim();
    }
    if (line.includes('Nome Contato:')) {
      parsedData.contact_name = line.split(':')[1].trim();
    }
    if (line.includes('Cidade:')) {
      parsedData.city = line.split(':')[1].trim();
    }
    if (line.includes('Tipo:')) {
      const rawType = line.split(':')[1].trim();
      parsedData.business_type = mapBusinessType(rawType);
    }
  }
}

return [{
  json: {
    phone_number: phoneNumber,
    message_to_send: agentOutput,
    onboarding_complete: isComplete,
    collected_data: parsedData
  }
}];

const restaurants = $input.all().map(item => item.json);

restaurants.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

const latestRestaurant = restaurants[0];

const onboardingData = $('Detectar Onboarding Completo').first().json;

return [{
  json: {
    ...onboardingData,
    restaurant_id: latestRestaurant.id,
    restaurant_data: latestRestaurant
  }
}];

const message = $('Detectar Onboarding Completo').first().json.message_to_send;
const phoneNumber = $('Extraer Datos WhatsApp').first().json.phone_number;

console.log('✅ [Preparar Output Onboarding] Onboarding en progreso');

return [{
  json: {
    output: message,
    phone_number: phoneNumber
  }
}];

const message = $('Detectar Onboarding Completo').first().json.message_to_send;

return [{
  json: {
    output: message,
    phone_number: $('Extraer Datos WhatsApp').first().json.phone_number
  }
}];

// 🔍 Vector Search Products - Enhanced
const userMessage = $input.first().json.message || $input.first().json.user_message;
const phoneNumber = $input.first().json.phone_number;
const sessionId = $input.first().json.session_id;
const restaurantId = $input.first().json.restaurant_id || $('Detectar Opción del Menú').first().json.user_data.restaurant_id;

console.log('🔍 [Vector Search] Buscando productos para:', userMessage);

let queryEmbedding;
try {
  const embeddingResponse = await $http.request({
    method: 'POST',
    url: 'https://api.openai.com/v1/embeddings',
    headers: {
      'Authorization': `Bearer ${$credentials.openAiApi.apiKey}`,
      'Content-Type': 'application/json'
    },
    body: {
      model: 'text-embedding-ada-002',
      input: userMessage
    }
  });

  if (embeddingResponse.statusCode !== 200) {
    console.error('❌ [Vector Search] OpenAI Embedding error:', embeddingResponse);
    return [{
      json: {
        user_message: userMessage,
        phone_number: phoneNumber,
        session_id: sessionId,
        restaurant_id: restaurantId,
        suggested_products: [],
        products_context: '',
        has_suggestions: false,
        error: 'embedding_generation_failed',
        ...($input.first().json)
      }
    }];
  }

  queryEmbedding = embeddingResponse.data[0].embedding;
  console.log('✅ [Vector Search] Embedding generado exitosamente');

} catch (error) {
  console.error('❌ [Vector Search] Error generando embedding:', error);
  return [{
    json: {
      user_message: userMessage,
      phone_number: phoneNumber,
      session_id: sessionId,
      restaurant_id: restaurantId,
      suggested_products: [],
      products_context: '',
      has_suggestions: false,
      error: 'embedding_error',
      ...($input.first().json)
    }
  }];
}

let matchingProducts = [];
try {
  const { data, error } = await $supabase.rpc('match_products_v2', {
    query_embedding: queryEmbedding,
    match_threshold: 0.65,
    match_count: 5
  });

  if (error) {
    console.error('❌ [Vector Search] Supabase RPC error:', error.message);
    matchingProducts = [];
  } else {
    matchingProducts = data || [];
    console.log(`✅ [Vector Search] ${matchingProducts.length} productos encontrados`);
  }

} catch (error) {
  console.error('❌ [Vector Search] Error en búsqueda vectorial:', error);
  matchingProducts = [];
}

let productsContext = '';

if (matchingProducts && matchingProducts.length > 0) {
  productsContext = '🔍 PRODUTOS ENCONTRADOS NO CATÁLOGO:\n\n';
  matchingProducts.forEach((p, idx) => {
    productsContext += `${idx + 1}. ${p.product_name}`;
    if (p.brand) productsContext += ` (${p.brand})`;
    productsContext += '\n';
    productsContext += `   Relevância: ${(p.similarity * 100).toFixed(0)}%\n`;

    if (p.alternative_names && Array.isArray(p.alternative_names) && p.alternative_names.length > 0) {
      productsContext += `   Também chamado: ${p.alternative_names.join(', ')}\n`;
    }
    productsContext += '\n';
  });
  productsContext += '💡 Use estes produtos como referência.\n';
}

return [{
  json: {
    user_message: userMessage,
    phone_number: phoneNumber,
    session_id: sessionId,
    restaurant_id: restaurantId,
    suggested_products: matchingProducts || [],
    products_context: productsContext,
    has_suggestions: matchingProducts && matchingProducts.length > 0,
    embedding_used: true,
    ...($input.first().json)
  }
}];

const input = $input.first().json;
const message = input.output || input.text || JSON.stringify(input);

return [{
  json: {
    output: message,
    phone_number: $('Extraer Datos WhatsApp').first().json.phone_number
  }
}];

const usuario = $input.first().json;

const tienePreferencias = usuario.category_preferences && 
                          Object.keys(usuario.category_preferences).length > 0;

return [{
  json: {
    ...usuario,
    setup_completo: tienePreferencias
  }
}];

const agentOutput = $input.first().json.output;

console.log('📥 [Detectar Setup] Output recibido del agente:', agentOutput);

const setupCompleto = agentOutput.includes('CONFIGURACAO_COMPLETA');

console.log('🔍 [Detectar Setup] Setup completo:', setupCompleto);

const phoneNumber = $('Extraer Datos WhatsApp').first().json.phone_number;
const userMessage = $('Extraer Datos WhatsApp').first().json.message;

let outputParaUsuario = agentOutput;

outputParaUsuario = outputParaUsuario
  .replace(/\{[\s\S]*?\}/g, '')
  .replace(/CONFIGURACAO_COMPLETA/g, '')
  .trim();

if (!outputParaUsuario || outputParaUsuario.length < 20) {
  outputParaUsuario = "Perfeito! Configurei tudo.\n\nDe agora em diante sou seu agente de compras. Sempre que precisar é só chamar 😊";
}

console.log('✅ [Detectar Setup] Output limpio para usuario:', outputParaUsuario);

return [{
  json: {
    phone_number: phoneNumber,
    setup_completo: setupCompleto,
    output: outputParaUsuario,
    output_completo: agentOutput,
    user_message: userMessage
  }
}];

const phoneNumber = $('Extraer Datos WhatsApp').first().json.phone_number;

console.log('📋 [Subir Precios] Iniciando flujo de subir precios');

const menuData = $('Detectar Opción del Menú').first().json;

return [{
  json: {
    phone_number: phoneNumber,
    user_data: menuData.user_data,
    restaurant_id: menuData.user_data.restaurant_id,
    person_id: menuData.user_data.id,
    message: $('Extraer Datos WhatsApp').first().json.message
  }
}];

return [{
  json: {
    output: '⚙️ Configurações em breve!

Por enquanto:
1️⃣ Enviar preços
2️⃣ Fazer pedido

Digite o número',
    phone_number: $('Detectar Opción del Menú').first().json.phone_number
  }
}];

const agentOutput = $input.first().json.output;
const usuario = $('Buscar Usuario').first().json;
const phoneNumber = $('Extraer Datos WhatsApp').first().json.phone_number;

const conversacionCompleta = agentOutput;

const preferencias = {
  preferencias_gerais: {
    prioridade: null,
    fornecedores_preferidos: []
  },
  categorias: {}
};

return [{
  json: {
    usuario_id: usuario.id,
    restaurant_id: usuario.restaurant_id,
    phone_number: phoneNumber,
    conversacion_completa: conversacionCompleta,
    necesita_procesamiento_llm: true
  }
}];

