const phoneNumber = $('Extraer Datos WhatsApp').first().json.phone_number;

console.log('✅ [Limpiar Output] Preferencias guardadas exitosamente');

const successMessage = "Pronto! Suas preferências foram salvas com sucesso. ✅";

return [{
  json: {
    output: successMessage,
    phone_number: phoneNumber,
    setup_completed: true
  }
}];

const agentOutput = $input.first().json.output;
const phoneNumber = $('Extraer Datos WhatsApp').first().json.phone_number;

console.log('🤖 [Detectar Acción] Output del agente:', agentOutput);

let accion = 'mostrar_respuesta';

if (agentOutput.includes('ACAO:FAZER_PEDIDO')) {
  accion = 'hacer_pedido';
} else if (agentOutput.includes('ACAO:CONFIGURAR')) {
  accion = 'configurar';
} else if (agentOutput.includes('ACAO:ENVIAR_PRECOS')) {
  accion = 'enviar_precos';
}

let outputLimpio = agentOutput
  .replace(/ACAO:FAZER_PEDIDO/g, '')
  .replace(/ACAO:CONFIGURAR/g, '')
  .replace(/ACAO:ENVIAR_PRECOS/g, '')
  .trim();

console.log('🎯 [Detectar Acción] Acción detectada:', accion);

return [{
  json: {
    accion: accion,
    output: outputLimpio,
    phone_number: phoneNumber,
    original_output: agentOutput
  }
}];

const session = $input.first().json;
const userMessage = $('Extraer Datos WhatsApp').first().json.message;
const phoneNumber = $('Extraer Datos WhatsApp').first().json.phone_number;
const userName = $('Extraer Datos WhatsApp').first().json.user_name;

return [{
  json: {
    session_id: session.session_id,
    phone_number: phoneNumber,
    user_name: userName,
    message: userMessage,
    session_context: "Novo usuário iniciando cadastro."
  }
}];

const preferenciasRaw = $input.first().json.output;

let preferencias;
try {
  const jsonLimpio = preferenciasRaw
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .replace(/^[^{]*/g, '')
    .replace(/[^}]*$/g, '')
    .trim();

  preferencias = JSON.parse(jsonLimpio);

  console.log('✅ JSON parseado correctamente:', preferencias);
} catch (error) {
  console.error('❌ Error parseando JSON:', error);
  console.error('Raw data:', preferenciasRaw);
  throw new Error('No se pudo parsear las preferencias: ' + preferenciasRaw);
}

const usuario = $('Buscar Usuario').first().json;

const prioridadMap = {
  'preco': 0.2,
  'equilibrio': 0.5,
  'qualidade': 0.8
};

const priceSensitivity = prioridadMap[preferencias.preferencias_gerais?.prioridade] || 0.5;

return [{
  json: {
    restaurant_id: usuario.restaurant_id,
    category_preferences: preferencias.categorias,
    price_sensitivity: priceSensitivity,
    preferred_suppliers: preferencias.preferencias_gerais?.fornecedores_preferidos || [],
    brand_loyalties: preferencias.categorias
  }
}];

const message = $('Extraer Datos WhatsApp').first().json.message.toLowerCase().trim();
const user = $('Verificar Setup Completo').first().json;

let option = null;

if (message.includes('1') || message.includes('preço') || message.includes('preco') || message.includes('lista de preço')) {
  option = 'upload_prices';
} else if (message.includes('2') || message.includes('pedido') || message.includes('compra') || message.includes('comprar')) {
  option = 'make_order';
} else if (message.includes('menu') || message.includes('opções') || message.includes('opcoes') || message.includes('oi') || message.includes('olá')) {
  option = 'show_menu';
} else if (message.includes('3') || message.includes('config') || message.includes('configuração')) {
  option = 'settings';
} else {
  option = 'chat';
}

return [{
  json: {
    detected_option: option,
    original_message: message,
    user_data: user,
    phone_number: $('Extraer Datos WhatsApp').first().json.phone_number
  }
}];

const agentOutput = $input.first().json.output;
const phoneNumber = $('Extraer Datos WhatsApp').first().json.phone_number;

console.log('💰 [Detectar Precios] Output del agente:', agentOutput);

const isPricesComplete = agentOutput.includes('PRECOS_CONFIRMADOS');

let preciosData = [];
let outputLimpio = agentOutput;

if (isPricesComplete) {
  try {
    const jsonMatch = agentOutput.match(/\[\s*\{[\s\S]*?\}\s*\]/);    if (jsonMatch) {
      preciosData = JSON.parse(jsonMatch[0]);
      console.log('✅ [Detectar Precios] Precios parseados:', preciosData.length);
    }

    outputLimpio = agentOutput
      .replace(/PRECOS_CONFIRMADOS/g, '')
      .replace(/\[\s*\{[\s\S]*?\}\s*\]/g, '')
      .trim();

    if (!outputLimpio || outputLimpio.length < 10) {
      outputLimpio = 'Pronto! Preços cadastrados com sucesso! ✅';
    }
  } catch (error) {
    console.error('❌ [Detectar Precios] Error parseando:', error);
  }
}

return [{
  json: {
    phone_number: phoneNumber,
    prices_complete: isPricesComplete,
    prices_data: preciosData,
    output: outputLimpio,
    original_output: agentOutput
  }
}];

// 🔄 Procesar cada precio y guardarlo
const pricesData = $input.first().json.prices_data;
const restaurantId = $('Preparar Datos Subir Precios').first().json.restaurant_id;

console.log('💾 [Procesar Precios] Procesando', pricesData.length, 'precios');

const results = [];

for (const item of pricesData) {
  try {
    // 1. Buscar o crear proveedor
    let supplierId = null;

    const { data: existingSupplier } = await $supabase
      .from('suppliers')
      .select('id')
      .ilike('company_name', item.fornecedor)
      .limit(1)
      .single();

    if (existingSupplier) {
      supplierId = existingSupplier.id;
      console.log('✅ Proveedor existente:', item.fornecedor, supplierId);
    } else {
      const { data: newSupplier, error } = await $supabase
        .from('suppliers')
        .insert({
          company_name: item.fornecedor,
          is_active: true,
          created_at: new Date().toISOString()
        })
        .select('id')
        .single();

      if (!error && newSupplier) {
        supplierId = newSupplier.id;
        console.log('✅ Nuevo proveedor creado:', item.fornecedor, supplierId);
      }
    }

    if (!supplierId) {
      console.error('❌ No se pudo obtener supplier_id para:', item.fornecedor);
      continue;
    }

    // 2. Buscar producto en master_list
    const { data: masterProduct } = await $supabase
      .from('master_list')
      .select('id')
      .ilike('product_name', `%${item.producto}%`)
      .limit(1)
      .single();

    const masterListId = masterProduct?.id || null;

    // 3. Guardar en supplier_mapped_products
    const { data: mappedProduct, error: mapError } = await $supabase
      .from('supplier_mapped_products')
      .insert({
        supplier_id: supplierId,
        master_list_id: masterListId,
        supplier_product_name: item.produto,
        current_unit_price: item.preco,
        price_per_unit_type: item.unidade,
        currency: 'BRL',
        mapping_confidence: masterListId ? 0.9 : 0.5,
        mapping_method: 'user_input',
        is_active: true,
        created_at: new Date().toISOString()
      })
      .select('id')
      .single();

    if (mapError) {
      console.error('❌ Error guardando producto:', mapError);
      continue;
    }

    // 4. Guardar en pricing_history
    await $supabase
      .from('pricing_history')
      .insert({
        supplier_id: supplierId,
        master_list_id: masterListId,
        supplier_mapped_product_id: mappedProduct.id,
        unit_price: item.preco,
        currency: 'BRL',
        price_per_unit_type: item.unidade,
        effective_date: new Date().toISOString(),
        snapshot_date: new Date().toISOString(),
        data_source: 'whatsapp_user',
        verification_status: 'pending',
        created_at: new Date().toISOString()
      });

    results.push({
      producto: item.produto,
      fornecedor: item.fornecedor,
      success: true
    });

    console.log('✅ Precio guardado:', item.produto, item.fornecedor, item.preco);

  } catch (error) {
    console.error('❌ Error procesando precio:', error);
    results.push({
      producto: item.produto,
      error: error.message
    });
  }
}

console.log(`✅ [Procesar Precios] ${results.filter(r => r.success).length}/${results.length} precios guardados`);

return [{
  json: {
    phone_number: $input.first().json.phone_number,
    total_prices: pricesData.length,
    saved_successfully: results.filter(r => r.success).length,
    results: results,
    output: `✅ ${results.filter(r => r.success).length} preços cadastrados com sucesso!`
  }
}];
